/**
 * @name Code injection via pandas.eval
 * @description Using pandas.eval with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PandasEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to pandas.eval() or DataFrame.eval()
    exists(API::CallNode call |
      (
        call = API::moduleImport("pandas").getMember("eval").getACall() or
        call = API::moduleImport("pandas").getMember("DataFrame").getMember("eval").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module PandasEvalFlow = TaintTracking::Global<PandasEvalConfig>;
import PandasEvalFlow::PathGraph

from PandasEvalFlow::PathNode source, PandasEvalFlow::PathNode sink
where PandasEvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code injection via pandas.eval from $@.", source.getNode(), "user input"

/**
 * @name SQL injection in pandas I/O
 * @description Using pandas SQL operations with untrusted input can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SQLInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to pandas SQL operations
    exists(API::CallNode call |
      (
        // pandas.read_sql, pandas.read_sql_query, pandas.read_sql_table
        call = API::moduleImport("pandas").getMember(["read_sql", "read_sql_query", "read_sql_table"]).getACall() or
        // DataFrame.to_sql
        call = API::moduleImport("pandas").getMember("DataFrame").getMember("to_sql").getACall()
      ) and
      // The query or table name arguments could be vulnerable
      sink = call.getArg(0) or sink = call.getArg(1)
    )
  }
}

module SQLInjectionFlow = TaintTracking::Global<SQLInjectionConfig>;
import SQLInjectionFlow::PathGraph

from SQLInjectionFlow::PathNode source, SQLInjectionFlow::PathNode sink
where SQLInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SQL injection from $@.", source.getNode(), "user input"

/**
 * @name SQL injection in pandas SQL operations
 * @description User-controlled input flowing into SQL queries without proper sanitization
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for SQL execution methods in pandas
    exists(API::CallNode call |
      (
        // pandas.io.sql methods that execute SQL
        call = API::moduleImport("pandas").getMember("io").getMember("sql").getMember("execute").getACall() or
        call = API::moduleImport("pandas").getMember("read_sql").getACall() or
        call = API::moduleImport("pandas").getMember("read_sql_query").getACall() or
        call = API::moduleImport("pandas").getMember("read_sql_table").getACall() or
        // Direct SQLAlchemy or sqlite3 execution
        call = API::moduleImport("sqlalchemy").getMember("engine").getMember("execute").getACall() or
        call = API::moduleImport("sqlite3").getMember("Connection").getMember("execute").getACall() or
        call = API::moduleImport("sqlite3").getMember("Cursor").getMember("execute").getACall()
      ) and
      // First argument is typically the SQL query
      sink = call.getArg(0)
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SQL injection from $@.", source.getNode(), "user input"

/**
 * @name XML External Entity (XXE) injection
 * @description Parsing XML with external entity expansion enabled can lead to file disclosure or SSRF
 * @kind path-problem
 * @problem.severity error
 * @id py/xxe-injection
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
