module XxeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for XML parsing functions that may be vulnerable to XXE
    exists(API::CallNode call |
      (
        // lxml parsing functions
        call = API::moduleImport("lxml").getMember("etree").getMember(["parse", "fromstring", "XML", "fromstring"]).getACall() or
        call = API::moduleImport("xml").getMember("etree").getMember(["parse", "fromstring", "XMLParser"]).getACall() or
        // pandas XML reading
        call = API::moduleImport("pandas").getMember("read_xml").getACall() or
        call = API::moduleImport("pandas").getMember("io").getMember("xml").getMember(["read_xml", "parse"]).getACall()
      ) and
      // First argument is typically the XML data or file path
      sink = call.getArg(0)
    )
  }
}

